# Build 18x15 output from the 3x6 mask of the test's 1-shape, tiled vertically
H,W=18,15
template={(0,2),(0,3),(1,1),(1,4),*( (2,c) for c in range(0,6) )}
colors=[2,3,1,8,7]
grid=[[0]*W for _ in range(H)]
for block,color in enumerate(colors):
    for dr,dc in template:
        grid[block*3+dr][3+dc]=color
print('dims',len(grid),set(map(len,grid)))
print('\n'.join('['+','.join(map(str,r))+'],' for r in grid))
